use std::fmt::Write as _;
use std::{env, fs, process};

struct Report {
    count: i64,
    name: String,
    note: String,
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn escape_json(value: &str, output: &mut String) {
    for character in value.chars() {
        match character {
            '"' => output.push_str("\\\""),
            '\\' => output.push_str("\\\\"),
            '\u{08}' => output.push_str("\\b"),
            '\u{0c}' => output.push_str("\\f"),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            character if character <= '\u{1f}' => {
                write!(output, "\\u{:04x}", character as u32).unwrap();
            }
            character => output.push(character),
        }
    }
}

fn main() {
    let path = match env::args().nth(1) {
        Some(path) => path,
        None => fail("missing input path"),
    };
    let input = match fs::read_to_string(&path) {
        Ok(input) => input,
        Err(error) => fail(format!("cannot read '{}': {}", path, error)),
    };

    let mut name: Option<String> = None;
    let mut count: Option<i64> = None;
    let mut note: Option<String> = None;

    for (line_number, raw_line) in input.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        let (field, value) = match line.split_once('\t') {
            Some(parts) => parts,
            None => fail(format!("line {}: expected a tab-separated field", line_number + 1)),
        };
        if field.is_empty() {
            fail(format!("line {}: missing field name", line_number + 1));
        }
        match field {
            "name" => {
                if name.is_some() {
                    fail(format!("line {}: duplicate field 'name'", line_number + 1));
                }
                name = Some(value.to_owned());
            }
            "count" => {
                if count.is_some() {
                    fail(format!("line {}: duplicate field 'count'", line_number + 1));
                }
                let parsed = match value.parse::<i64>() {
                    Ok(parsed) => parsed,
                    Err(error) => fail(format!(
                        "line {}: invalid count: {}",
                        line_number + 1,
                        error
                    )),
                };
                count = Some(parsed);
            }
            "note" => {
                if note.is_some() {
                    fail(format!("line {}: duplicate field 'note'", line_number + 1));
                }
                note = Some(value.to_owned());
            }
            other => fail(format!("line {}: unknown field '{}',", line_number + 1, other)),
        }
    }

    let report = Report {
        count: count.unwrap_or_else(|| fail("missing field 'count'")),
        name: name.unwrap_or_else(|| fail("missing field 'name'")),
        note: note.unwrap_or_else(|| fail("missing field 'note'")),
    };

    let mut output = String::from("{\"count\":");
    output.push_str(&report.count.to_string());
    output.push_str(",\"name\":\"");
    escape_json(&report.name, &mut output);
    output.push_str("\",\"note\":\"");
    escape_json(&report.note, &mut output);
    output.push_str("\"}\n");
    print!("{}", output);
}
